import {CLASSES,ITEMS,SLOTS,PROFESSIONS,RECIPES,talents} from './content.js';
import {DOORS,INTERIORS,NODES,bounds,safePosition,sceneNPCs} from './world.js';
import {sprite} from './art.js';
import {createCompanion,newRelationship} from './companion.js';
const $=id=>document.getElementById(id);
const freshWorld=()=>({elapsed:0,profession:null,professionXP:{},resources:{},house:{owned:false,stage:0,garden:false,hearth:false,plantedAt:null},relationship:newRelationship(),contract:null,blessedUntil:0,mountUntil:0,visits:[]});
const item=(id,qty=1)=>({id,qty});
const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
export function createRPG(api){
 const {state,toast,saveGame,openModal,closeModal}=api;let selected=null,drag=null,draggedAt=0,busy=false,jobTimer=null,romance=null;
 function reset(){state.scene='overworld';state.companion=null;state.romancePose=null;state.pendingHits=[];state.player.action=null;state.world=freshWorld();state.loot=[];state.summons=[];state.player.bag=Array(24).fill(null);const type=state.player.type;state.player.equipment={weapon:item(CLASSES[type].weapon),body:item(type==='paladin'?'armor':type==='rogue'?'leathercoat':'robe'),head:null,feet:item('boots'),ring:null,offhand:type==='paladin'?item('shield'):null,tool:null};state.player.learned=[];give('potion',3);give('bread',2);give('cloth',2);give('seed',3);give('hammer');sync();state.player.hp=state.player.maxHp;state.player.mp=state.player.maxMp;}
 function restore(saved){state.scene=saved.scene&&(['overworld','district',...Object.keys(INTERIORS)].includes(saved.scene))?saved.scene:'overworld';const old=saved.world||{};state.world={...freshWorld(),...old,house:{...freshWorld().house,...old.house},relationship:{...newRelationship(),...old.relationship},resources:{...old.resources},professionXP:{...old.professionXP}};state.loot=Array.isArray(saved.loot)?saved.loot.filter(l=>ITEMS[l.item]).slice(0,100):[];state.summons=[];state.companion=null;state.romancePose=null;const p=state.player;
  p.level=Math.max(1,Math.min(100,Number(p.level)||1));p.gold=Math.max(0,Number(p.gold)||0);state.world.elapsed=Math.max(0,Number(state.world.elapsed)||0);if(!PROFESSIONS[state.world.profession])state.world.profession=null;state.world.house.stage=Math.max(0,Math.min(4,Number(state.world.house.stage)||0));const rr=state.world.relationship;rr.bond=Math.max(0,Math.min(100,Number(rr.bond)||30));rr.events=Array.isArray(rr.events)?rr.events.filter(e=>typeof e==='string').slice(0,12):[];rr.visited=Array.isArray(rr.visited)?rr.visited:[];rr.memories=Array.isArray(rr.memories)?rr.memories:[];
  p.bag=Array.isArray(p.bag)?Array.from({length:24},(_,i)=>{const it=p.bag[i];return it&&ITEMS[it.id]?item(it.id,Math.max(1,Math.min(Number(it.qty)||1,ITEMS[it.id].stack||1))):null;}):null;
  if(!p.bag){p.bag=Array(24).fill(null);give('potion',Math.max(0,p.potions||0));give('bread',2);give('hammer');give('seed',3);}
  p.equipment={weapon:item(CLASSES[p.type].weapon),...p.equipment};for(const [slot,it]of Object.entries(p.equipment))if(!it||!ITEMS[it.id]||ITEMS[it.id].slot!==slot)p.equipment[slot]=null;
  p.learned=Array.isArray(p.learned)?p.learned.filter(id=>talents(p.type).some(t=>t.id===id)):[];sync();Object.assign(p,safePosition(state.scene,p.x,p.y,state.quest));
 }
 function serialize(){return{scene:state.scene,world:state.world,loot:state.loot};}
 function count(id){return(state.player.bag||[]).reduce((n,it)=>n+(it?.id===id?it.qty:0),0);}
 function give(id,qty=1){const def=ITEMS[id];if(!def||qty<1)return false;const bag=state.player.bag;if(!bag)return false;const capacity=bag.reduce((n,it)=>n+(!it?(def.stack||1):it.id===id?(def.stack||1)-it.qty:0),0);if(capacity<qty){toast('В сумке нет места. Освободите ячейку.');return false;}for(const it of bag){if(it?.id===id&&it.qty<(def.stack||1)){const n=Math.min(qty,(def.stack||1)-it.qty);it.qty+=n;qty-=n;if(!qty)break;}}for(let i=0;qty&&i<bag.length;i++)if(!bag[i]){const n=Math.min(qty,def.stack||1);bag[i]=item(id,n);qty-=n;}state.player.potions=count('potion');return true;}
 function take(id,qty=1){if(count(id)<qty)return false;const b=state.player.bag;for(let i=b.length-1;i>=0&&qty;i--)if(b[i]?.id===id){const n=Math.min(qty,b[i].qty);b[i].qty-=n;qty-=n;if(b[i].qty===0)b[i]=null;}state.player.potions=count('potion');return true;}
 function stats(){const p=state.player,base=CLASSES[p.type],bonus={attack:0,armor:0,health:0,mana:0,speed:0,regen:0,spell:0,healing:0,lifesteal:0,crit:p.type==='rogue'?.12:.04,dash:0,summons:0};for(const it of Object.values(p.equipment||{})){const d=ITEMS[it?.id];if(d)for(const key of Object.keys(bonus))bonus[key]+=d[key]||0;}for(const t of talents(p.type))if(p.learned?.includes(t.id))for(const[k,v]of Object.entries(t.bonus))bonus[k]+=v;
  if(state.world?.blessedUntil>state.world?.elapsed)bonus.armor+=5;if(state.world?.mountUntil>state.world?.elapsed)bonus.speed+=22;
  if(state.world?.relationship?.restedUntil>state.world?.elapsed)bonus.regen+=1.5;
  return{...base,...bonus,damage:base.damage+bonus.attack,speed:base.speed+bonus.speed,regen:4.2+bonus.regen,maxHp:base.hp+(p.level-1)*16+bonus.health,maxMp:base.mp+(p.level-1)*8+bonus.mana};
 }
 function sync(){if(!state.player.bag)return;const p=state.player,s=stats();p.maxHp=s.maxHp;p.maxMp=s.maxMp;p.hp=Math.min(p.maxHp,p.hp);p.mp=Math.min(p.maxMp,p.mp);p.potions=count('potion');}
 function xp(amount){const w=state.world,key=w.profession;if(key)w.professionXP[key]=(w.professionXP[key]||0)+Math.round(amount*(state.player.equipment?.tool?1.2:1));}
 function level(){return 1+Math.floor((state.world.professionXP[state.world.profession]||0)/25);}
 function nearby(){if(state.stage!=='playing'||state.dialog)return null;const p=state.player,s=state.scene||'overworld',dist=v=>Math.hypot(p.x-v.x,p.y-v.y);
  const love=romance?.nearby();
  if(s==='overworld'&&p.y>1461&&p.x>415&&p.x<615)return{kind:'world',action:'district',label:'В рыночный квартал',x:512,y:1490};
  if(s==='district'){const d=DOORS.find(d=>dist(d)<51);if(d)return{kind:'world',action:'door',door:d,label:d.id==='forest'?'В Тихолесье':d.id==='home'?'Осмотреть дом':'Войти · '+d.label};}
  if(INTERIORS[s]){if(p.y>535&&Math.abs(p.x-320)<65)return{kind:'world',action:'exit',label:'Выйти наружу'};if(dist({x:320,y:267})<69||s==='home'&&dist({x:415,y:485})<55)return{kind:'world',action:'service',label:s==='home'?'Дом и Амо':'Поговорить · '+INTERIORS[s].npc};}
  const loot=state.loot?.find(l=>l.scene===s&&dist(l)<33);if(loot)return{kind:'world',action:'loot',loot,label:'Поднять · '+ITEMS[loot.item].name};
  const node=NODES.find(n=>n.scene===s&&dist(n)<40&&(state.world.resources[n.id]||0)<=state.world.elapsed);if(node)return{kind:'world',action:'gather',node,label:'Собрать · '+node.name};
  if(s==='district'){const n=sceneNPCs(state).find(n=>n.id!=='amo-companion'&&dist(n)<44);if(n)return{kind:'world',action:'ambient',npc:n,label:'Поговорить · '+n.name};}
  return love||null;
 }
 function travel(scene,x,y){state.scene=scene;Object.assign(state.player,safePosition(scene,x,y,state.quest));state.projectiles=[];state.areas=[];state.summons=[];state.pendingHits=[];api.resetInputs();api.snapCamera();if(!state.world.visits.includes(scene))state.world.visits.push(scene);closeModal();saveGame();}
 function interact(near){if(near.action==='district'){travel('district',457,951);toast('Рыночный квартал · здесь жизнь продолжается');}
  if(near.action==='companion'){openModal('companion');return;}
  if(near.action==='door'){const d=near.door;if(d.id==='forest')travel('overworld',512,1440);else if(d.id==='home'&&!state.world.house.owned)openModal('housing');else{travel(d.id,320,525);toast(INTERIORS[d.id].name);}}
  if(near.action==='exit'){const d=DOORS.find(d=>d.id===(state.scene==='chapel'?'church':state.scene));travel('district',d.x,d.y+46);}
  if(near.action==='service')openModal('service');
  if(near.action==='gather'){const n=near.node,qty=(n.item==='wood'?2:1)+(n.item==='ore'&&state.player.equipment?.tool?.id==='pickaxe'?1:0);if(give(n.item,qty)){state.world.resources[n.id]=state.world.elapsed+45;xp(4);toast('Получено: '+ITEMS[n.item].name+' ×'+qty,true);api.burst(n.x,n.y,'#e8d39f');romance.assist('gather',n.item);saveGame();}}
  if(near.action==='loot'){if(give(near.loot.item,near.loot.qty)){state.loot.splice(state.loot.indexOf(near.loot),1);toast('Находка: '+ITEMS[near.loot.item].name,true);saveGame();}}
  if(near.action==='ambient'){const lines={mason:'Камень любит терпение. Загляни к мастеру Брану — он научит ремеслу.',weaver:'На рынке берут и ткань, и травы. Хорошему товару здесь всегда рады.',porter:'Работы много. В трактире нужны руки, а в конюшнях — люди, которые не боятся испачкаться.',child:'Говорят, у южной дороги продают старый дом. С новым очагом он станет совсем другим.',guard:'Заказы капитана висят в замке. За чистую дорогу казна платит честно.',visitor:'В часовне можно пересмотреть свой путь. А в церкви — перевести дух.'};api.dialog([[near.npc.name,lines[near.npc.id]||'Доброго пути, странник.',near.npc.type,'ЖИТЕЛЬ КВАРТАЛА']]);}
 }
 function onKill(e){if(Math.random()<.8||e.type==='boss'){const id=e.type==='boss'?'gem':['ore','cloth','leather','herb'][state.killCount%4];state.loot.push({scene:state.scene,x:e.x+13,y:e.y,item:id,qty:e.type==='boss'?2:1});}if(state.player.type==='necromancer'||stats().lifesteal)state.player.hp=Math.min(state.player.maxHp,state.player.hp+8);sync();}
 function update(dt){if(state.stage!=='playing'||state.paused||state.dialog)return;state.world.elapsed+=dt;romance?.update(dt);for(const e of state.enemies){if(e.poison>0&&e.hp>0){e.poison-=dt;e.poisonTick=(e.poisonTick||0)+dt;if(e.poisonTick>1){e.poisonTick=0;api.hitEnemy(e,5+state.player.level);}}e.slow=Math.max(0,(e.slow||0)-dt);}
  state.summons=state.summons.filter(s=>{s.life-=dt;if(s.life<=0||s.hp<=0)return false;if(s.action){s.action.t+=dt;if(s.action.t>s.action.duration)s.action=null;}const target=state.enemies.filter(e=>e.hp>0&&(e.type!=='boss'||state.quest>=3)).sort((a,b)=>Math.hypot(a.x-s.x,a.y-s.y)-Math.hypot(b.x-s.x,b.y-s.y))[0];const dest=target&&Math.hypot(target.x-state.player.x,target.y-state.player.y)<280?target:state.player,d=Math.hypot(dest.x-s.x,dest.y-s.y),a=Math.atan2(dest.y-s.y,dest.x-s.x);s.dir=Math.abs(Math.cos(a))>.65?(Math.cos(a)>0?'right':'left'):(Math.sin(a)>0?'down':'up');s.moving=false;if(d>32){api.moveEntity(s,Math.cos(a)*(s.type==='undeadpaladin'?70:100)*dt,Math.sin(a)*(s.type==='undeadpaladin'?70:100)*dt);s.moving=true;}s.cd-=dt;if(target===dest&&d<(s.type==='undeadpaladin'?65:44)&&s.cd<=0){s.cd=s.type==='undeadpaladin'?1.35:.95;s.action={kind:'attack',t:0,duration:.7,dir:s.dir};api.queueHit(.32,()=>{if(s.hp>0&&target.hp>0&&distance(target,s)<80)api.hitEnemy(target,(s.type==='undeadpaladin'?59:18)+state.player.level*3);});}return true;});
 }
 const icon=(id,cls='')=>`<span class="item-icon ${cls}" style="background-position:${ITEMS[id].icon%6/5*100}% ${Math.floor(ITEMS[id].icon/6)/3*100}%" role="img" aria-label="${ITEMS[id].name}"></span>`;
 const button=(action,label,extra='',disabled=false)=>`<button data-rpg="${action}" ${extra} ${disabled?'disabled':''} class="rpg-button">${label}</button>`;
 const tabbar=active=>`<nav class="folio-tabs">${[['inventory','Сумка'],['character','Герой'],['talents','Умения'],['professions','Ремесло']].map(([k,v])=>`<button class="${active===k?'active':''}" data-rpg="tab" data-tab="${k}">${v}</button>`).join('')}</nav>`;
 const heading=(kicker,title)=>`<small class="modal-kicker">${kicker}</small><h2>${title}</h2>`;
 function slotHTML(slot,it,label=''){return`<button class="bag-slot ${it?'filled':''} ${selected===slot?'selected':''}" data-slot="${slot}" aria-label="${label?label+': ':''}${it?ITEMS[it.id].name:'Пустая ячейка'}" title="${it?ITEMS[it.id].name:label||'Пусто'}">${it?icon(it.id):`<span class="slot-empty">${label||'·'}</span>`}${it?.qty>1?`<b>${it.qty}</b>`:''}</button>`;}
 function readSlot(s){if(!s)return null;const[a,k]=s.split(':');return a==='bag'?state.player.bag[+k]:state.player.equipment[k];}
 function setSlot(s,it){const[a,k]=s.split(':');if(a==='bag')state.player.bag[+k]=it;else state.player.equipment[k]=it;}
 function fits(s,it){return !it||s.startsWith('bag:')||ITEMS[it.id].slot===s.split(':')[1];}
 function moveSlot(from,to){if(!from||!to||from===to)return;const a=readSlot(from),b=readSlot(to);if(!a)return;if(!fits(to,a)||!fits(from,b)){toast('Этот предмет не подходит в выбранную ячейку.');return;}if(a.id===b?.id&&ITEMS[a.id].stack&&to.startsWith('bag:')){const n=Math.min(a.qty,ITEMS[a.id].stack-b.qty);a.qty-=n;b.qty+=n;if(!a.qty)setSlot(from,null);}else{setSlot(from,b||null);setSlot(to,a);}selected=to;sync();saveGame();renderCurrent();}
 function details(){const it=readSlot(selected);if(!it)return'<div class="item-details"><strong>Всё нужное — под рукой</strong><p>Перетаскивайте предметы между ячейками. Вещь можно надеть, использовать или оставить на земле. На телефоне также работают два касания: предмет, затем пустая ячейка.</p></div>';const d=ITEMS[it.id];return`<div class="item-details">${icon(it.id)}<div><strong>${d.name}</strong><p>${d.desc}</p><small>Цена продажи: ${Math.max(1,Math.floor(d.value*.55))} мон. · Количество: ${it.qty}</small></div><div class="item-actions">${d.slot?button(selected.startsWith('equip:')?'unequip':'equip',selected.startsWith('equip:')?'Снять':'Надеть'):['potion','bread'].includes(it.id)?button('consume','Использовать'):''}${it.qty>1?button('split','Разделить'):''}${button('drop','На землю')}</div></div>`;}
 function characterCanvas(){const cv=$('paperdoll');if(!cv)return;const c=cv.getContext('2d');c.clearRect(0,0,cv.width,cv.height);c.strokeStyle='#b18c4a55';c.lineWidth=1;c.beginPath();c.arc(120,160,90,0,7);c.stroke();c.beginPath();c.arc(120,160,72,0,7);c.stroke();sprite(c,120,260,state.player.type,'down',state.time,4.5);}
 function renderCurrent(){renderModal(state.modal);}
 function renderModal(kind){if(romance?.renderModal(kind))return true;if(!['inventory','character','talents','professions','service','housing'].includes(kind))return false;const p=state.player,w=state.world,el=$('modal-content');$('modal').querySelector('.modal-card').classList.add('rpg-folio');let html='';
  if(['inventory','character','talents','professions'].includes(kind))html=heading('ДОРОЖНАЯ КНИГА МОРРИГАН',kind==='inventory'?'Кожаная сумка':kind==='character'?CLASSES[p.type].label:kind==='talents'?'Древо пути':'Ремесло и труд')+tabbar(kind);
  if(kind==='inventory')html+=`<div class="inventory-gear">${Object.entries(SLOTS).map(([k,label])=>`<div><small>${label}</small>${slotHTML('equip:'+k,p.equipment[k],label)}</div>`).join('')}</div><div class="bag-meta"><span>✦ ${p.gold} монет</span><span>${p.bag.filter(Boolean).length} / 24 ячейки</span></div><div class="bag-grid">${p.bag.map((it,i)=>slotHTML('bag:'+i,it)).join('')}</div>${details()}<p class="folio-hint">Зажмите и перетащите · или выберите предмет и ячейку</p>`;
  if(kind==='character'){const s=stats();html+=`<div class="hero-sheet"><div class="gear-column">${['head','body','feet'].map(k=>`<div class="gear-wrap"><small>${SLOTS[k]}</small>${slotHTML('equip:'+k,p.equipment[k],SLOTS[k])}</div>`).join('')}</div><div class="hero-figure"><canvas id="paperdoll" width="240" height="300"></canvas><h3>Морриган</h3><small>${p.level} УРОВЕНЬ · ${CLASSES[p.type].label}</small></div><div class="gear-column">${['weapon','offhand','ring','tool'].map(k=>`<div class="gear-wrap"><small>${SLOTS[k]}</small>${slotHTML('equip:'+k,p.equipment[k],SLOTS[k])}</div>`).join('')}</div></div><div class="stat-grid">${[['Жизнь',`${Math.ceil(p.hp)} / ${p.maxHp}`],['Энергия',`${Math.ceil(p.mp)} / ${p.maxMp}`],['Урон',s.damage],['Броня',s.armor],['Критический шанс',Math.round(s.crit*100)+'%'],['Скорость',s.speed],['Опыт',p.xp+' / '+p.level*60],['Восстановление',s.regen.toFixed(1)+'/с']].map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</div>${details()}${button('tab','Открыть сумку','data-tab="inventory"')}`;}
  if(kind==='talents'){const ts=talents(p.type),points=Math.max(0,p.level-(p.learned?.length||0));html+=`<div class="bag-meta"><span>${CLASSES[p.type].motto}</span><strong>Очки: ${points}</strong></div><p>Три боевых умения доступны сразу. Каждый уровень даёт очко для одной из двух ветвей.</p><div class="talent-tree">${[0,1].map(b=>`<section><h3>${ts[b*3].branch}</h3>${ts.slice(b*3,b*3+3).map(t=>{const learned=p.learned.includes(t.id),can=!t.requires||p.learned.includes(t.requires);return`<article class="talent-node ${learned?'learned':''}"><span class="talent-rune">${learned?'✦':'◇'}</span><strong>${t.name}</strong><p>${t.desc}</p>${button('learn',learned?'Изучено':'Изучить · 1 очко',`data-id="${t.id}"`,learned||!points||!can)}</article>`;}).join('')}</section>`).join('')}</div><div class="skill-description-list">${CLASSES[p.type].skills.map((s,i)=>`<p><b>${i+1} · ${s}</b> · перезарядка ${CLASSES[p.type].cooldowns[i]} с</p>`).join('')}</div>`;}
  if(kind==='professions')html+=professionHTML()+craftHTML();
  if(kind==='service')html+=serviceHTML();
  if(kind==='housing')html+=housingHTML();
  el.innerHTML=html;characterCanvas();return true;
 }
 function professionHTML(){const w=state.world;return`<p>Выберите дело по душе. Специализация даёт заработок, опыт и доступ к своим рецептам. Смена дела стоит 25 монет; изученные уровни сохраняются.</p><div class="profession-grid">${Object.entries(PROFESSIONS).map(([key,d])=>`<article class="profession-card ${w.profession===key?'chosen':''}">${icon(d.reward)}<h3>${d.name}</h3><p>${d.desc}</p><small>Уровень ${1+Math.floor((w.professionXP[key]||0)/25)} · опыт ${w.professionXP[key]||0}</small>${button('profession',w.profession===key?'Ваше ремесло':w.profession?'Сменить · 25 мон.':'Выбрать',`data-profession="${key}"`,w.profession===key)}</article>`).join('')}</div>${w.profession?`<div class="work-order"><h3>Заказ подмастерью</h3><p>${PROFESSIONS[w.profession].name}: выполните небольшую работу. Награда ${8+level()*2} монет, материал и опыт.</p>${button('work','Приступить к работе · 2 сек.','data-job="profession"')}<div id="work-progress"></div></div>`:''}`;}
 function craftHTML(){const w=state.world;return`<h3>Верстак и рецепты</h3><div class="recipe-list">${RECIPES.map(r=>{const can=w.profession===r.profession,have=Object.entries(r.cost).every(([id,n])=>count(id)>=n);return`<article>${icon(r.out)}<div><strong>${r.name}</strong><p>${Object.entries(r.cost).map(([id,n])=>`${ITEMS[id].name} ${count(id)}/${n}`).join(' · ')}</p><small>${PROFESSIONS[r.profession].name} · результат ×${r.qty}</small></div>${button('craft','Создать',`data-id="${r.id}"`,!can||!have)}</article>`;}).join('')}</div>`;}
 function shopHTML(){return`<h3>На прилавке</h3><div class="shop-list">${['potion','bread','helm','armor','boots','shield','ring','wood','ore','herb','plank','brick','leather','cloth','seed','pickaxe'].map(id=>`<article>${icon(id)}<span><strong>${ITEMS[id].name}</strong><small>${ITEMS[id].value} монет</small></span>${button('buy','Купить',`data-id="${id}"`,state.player.gold<ITEMS[id].value)}</article>`).join('')}</div><h3>Продать из сумки</h3><div class="shop-list">${state.player.bag.map((it,i)=>it?`<article>${icon(it.id)}<span><strong>${ITEMS[it.id].name} ×${it.qty}</strong><small>${Math.max(1,Math.floor(ITEMS[it.id].value*.55))} монет / шт.</small></span>${button('sell','Продать 1',`data-index="${i}"`)}</article>`:'').join('')||'<p>Сумка пуста.</p>'}</div>`;}
 function serviceHTML(){const room=INTERIORS[state.scene];if(!room)return housingHTML();let html=heading(room.name,room.npc)+`<div class="bag-meta"><span>✦ ${state.player.gold} монет</span><span>${CLASSES[state.player.type].label} · ${state.player.level} ур.</span></div>`;
  if(room.service==='inn')html+=`<p>Пахнет хлебом и яблочным сидром. У очага спорят торговцы, а за стойкой всегда найдётся работа.</p>${button('rest','Снять комнату · 8 монет','data-cost="8"')}${button('work','Помочь на кухне · 10 монет и хлеб','data-job="inn"')}<div id="work-progress"></div>`;
  if(room.service==='castle'){const ct=state.world.contract;html+=`<p>Капитан платит за безопасную дорогу. Во дворе слышны удары тренировочных мечей.</p><h3>Заказ: очистить лесную дорогу</h3><p>${ct?`Побеждено теней: ${Math.min(3,state.killCount-ct.start)} / 3. Награда: 45 монет и руда.`:'Победите трёх теней. Можно брать повторно; противники вернутся на северную дорогу.'}</p>${button(ct?'claim-contract':'contract',ct?'Получить награду':'Взять заказ', '',!!ct&&state.killCount-ct.start<3)}`;}
  if(room.service==='church')html+=`<p>У витражей тихо. Сестра Ива перевяжет раны и благословит дорогу.</p>${button('rest','Исцеление · '+(state.player.type==='paladin'?'даром':'6 монет'),`data-cost="${state.player.type==='paladin'?0:6}"`)}${button('bless','Благословение · броня +5 на 5 минут · 12 монет')}${button('chapel','Войти в боковую часовню')}`;
  if(room.service==='chapel')html+=`<p>Здесь хранят имена тех, кого мир едва не забыл. На каменном алтаре можно заново осмыслить свой путь.</p>${button('tab','Открыть древо умений','data-tab="talents"')}${button('respec','Вернуть очки умений · 40 монет')}`;
  if(room.service==='stables')html+=`<p>Лошади нетерпеливо бьют копытами. Конюху нужна помощь с кормом и сбруей.</p>${button('work','Ухаживать за лошадьми · 9 монет и кожа','data-job="stables"')}<div id="work-progress"></div>${button('ride','Арендовать лошадь · скорость +22 на 2 минуты · 15 монет')}`;
  if(['market','shop'].includes(room.service))html+=shopHTML();
  if(room.service==='workshop')html+=professionHTML()+craftHTML();
  if(room.service==='home')html+=housingHTML(false);
  return html;
 }
 const houseStages=['Участок','Фундамент','Стены','Крыша','Общий дом'];
 const buildCosts=[{gold:40,plank:4,brick:4},{gold:60,plank:6},{gold:80,plank:8,brick:6},{gold:65,plank:4,cloth:4}];
 function housingHTML(withHeading=true){const h=state.world.house;let html=(withHeading?heading('ЖИЗНЬ ПОСЛЕ ПРИКЛЮЧЕНИЯ','Дом для двоих'):'')+`<p>${state.quest<5?'Сначала верните Амо из святилища. Затем вы сможете купить дом или построить его вместе.':'Амо: «Мне не нужен дворец. Только окно на утреннее солнце. И чтобы ты возвращался домой». '}</p>`;
  if(!h.owned)return html+`<div class="house-options"><article><h3>Старый участок</h3><p>80 монет. Четыре этапа строительства из досок, камня и ткани.</p>${button('buy-plot','Купить участок · 80 монет','',state.quest<5||state.player.gold<80)}</article><article><h3>Халупа у дороги</h3><p>220 монет. Готовый скромный дом, который можно обустроить.</p>${button('buy-shack','Купить дом · 220 монет','',state.quest<5||state.player.gold<220)}</article></div>`;
  html+=`<div class="house-stages">${houseStages.map((name,i)=>`<span class="${i<=h.stage?'done':''}">${i<h.stage?'✓':i===h.stage?'✦':'◇'} ${name}</span>`).join('')}</div>`;
  if(h.stage<4){const cost=buildCosts[h.stage],can=Object.entries(cost).every(([k,n])=>k==='gold'?state.player.gold>=n:count(k)>=n);html+=`<h3>Следующий этап: ${houseStages[h.stage+1]}</h3><p>${Object.entries(cost).map(([k,n])=>k==='gold'?`${n} монет`:`${ITEMS[k].name} ${count(k)}/${n}`).join(' · ')}</p>${button('build','Строить вместе с Амо','',!can)}`;}
  else{html+=`<p>Дом достроен. Здесь можно восстановить силы, поговорить с Амо и заняться огородом.</p>${button('rest','Отдохнуть вместе · бесплатно','data-cost="0"')}${button('amo','Поговорить с Амо')}`;
   if(!h.hearth)html+=button('hearth','Сложить очаг · 35 монет, 4 камня');else html+='<p>✦ В очаге горит огонь. Дома тепло.</p>';
   if(!h.garden)html+=button('garden','Разбить огород · 30 монет, 3 доски');else{const remaining=h.plantedAt===null?null:Math.max(0,45-(state.world.elapsed-h.plantedAt));html+=remaining===null?button('plant','Посадить пшеницу · 1 семя'):remaining>0?`<p>Пшеница растёт. Осталось ${Math.ceil(remaining)} сек. игрового времени.</p>`:button('harvest','Собрать урожай · 3 пшеницы');}
  }return html+button('enter-home','Зайти в дом');
 }
 function pay(gold){if(state.player.gold<gold){toast('Недостаточно монет');return false;}state.player.gold-=gold;return true;}
 function work(job){if(busy)return;const scene=state.scene;busy=true;const el=$('work-progress');if(el)el.innerHTML='<div class="working"><i></i><span>Работаем…</span></div>';document.querySelectorAll('[data-rpg="work"]').forEach(el=>el.disabled=true);jobTimer=setTimeout(()=>{busy=false;if(state.scene!==scene)return;const reward=job==='profession'?8+level()*2:job==='inn'?10:9;state.player.gold+=reward;give(job==='profession'?PROFESSIONS[state.world.profession].reward:job==='inn'?'bread':'leather',job==='profession'?2:1);xp(7);toast('Работа выполнена · +'+reward+' монет',true);saveGame();if(state.modal)renderCurrent();},1800);}
 function consume(){const it=readSlot(selected);if(!it)return;if(it.id==='potion'){api.heal();}else if(it.id==='bread'){if(take('bread')){state.player.hp=Math.min(state.player.maxHp,state.player.hp+35);state.player.mp=Math.min(state.player.maxMp,state.player.mp+20);toast('Хлеб восстановил силы',true);}}saveGame();renderCurrent();}
 function onAction(e){const target=e.target.closest('[data-rpg]');if(!target)return;const action=target.dataset.rpg,id=target.dataset.id,p=state.player,w=state.world;if(target.disabled)return;if(busy){toast('Работа скоро закончится');return;}
  if(action==='tab'){selected=null;openModal(target.dataset.tab);return;}
  if(action==='equip'){const it=readSlot(selected);if(it)moveSlot(selected,'equip:'+ITEMS[it.id].slot);return;}
  if(action==='unequip'){const n=p.bag.findIndex(v=>!v);if(n<0)toast('Сумка заполнена');else moveSlot(selected,'bag:'+n);return;}
  if(action==='consume'){consume();return;}
  if(action==='split'){const it=readSlot(selected),n=p.bag.findIndex(it=>!it);if(!it||it.qty<2)return;if(n<0){toast('Нужна пустая ячейка');return;}const amount=Math.floor(it.qty/2);it.qty-=amount;p.bag[n]=item(it.id,amount);}
  if(action==='drop'){const it=readSlot(selected);if(!it)return;state.loot.push({scene:state.scene,x:p.x+12,y:p.y+7,item:it.id,qty:it.qty});setSlot(selected,null);selected=null;toast('Предмет оставлен рядом. Его можно подобрать.');}
  if(action==='learn'){const t=talents(p.type).find(t=>t.id===id);if(!t||p.learned.includes(id)||p.learned.length>=p.level||t.requires&&!p.learned.includes(t.requires))return;p.learned.push(id);sync();toast('Изучено: '+t.name,true);}
  if(action==='profession'){const key=target.dataset.profession;if(!PROFESSIONS[key]||w.profession===key)return;if(w.profession&&!pay(25))return;w.profession=key;toast('Ваше ремесло: '+PROFESSIONS[key].name,true);}
  if(action==='craft'){const r=RECIPES.find(r=>r.id===id);if(!r||w.profession!==r.profession||!Object.entries(r.cost).every(([k,n])=>count(k)>=n))return;const old=structuredClone(p.bag);for(const[k,n]of Object.entries(r.cost))take(k,n);if(!give(r.out,r.qty)){p.bag=old;sync();return;}xp(r.xp);toast('Создано: '+ITEMS[r.out].name+' ×'+r.qty,true);}
  if(action==='buy'){const d=ITEMS[id];if(!d||p.gold<d.value)return;if(give(id)){p.gold-=d.value;toast('Куплено: '+d.name,true);}}
  if(action==='sell'){const i=+target.dataset.index,it=p.bag[i];if(!it)return;p.gold+=Math.max(1,Math.floor(ITEMS[it.id].value*.55));it.qty--;if(!it.qty)p.bag[i]=null;sync();}
  if(action==='rest'){if(!pay(+target.dataset.cost))return;p.hp=p.maxHp;p.mp=p.maxMp;toast('Здоровье и энергия восстановлены',true);}
  if(action==='bless'){if(!pay(12))return;w.blessedUntil=w.elapsed+300;toast('Благословение Рассвета · броня +5',true);}
  if(action==='ride'){if(!pay(15))return;w.mountUntil=w.elapsed+120;toast('Лошадь арендована · скорость +22',true);}
  if(action==='respec'){if(!p.learned.length){toast('Пока нет изученных талантов');return;}if(!pay(40))return;p.learned=[];sync();toast('Очки пути возвращены',true);}
  if(action==='work'){work(target.dataset.job);return;}
  if(action==='contract'){if(w.contract)return;w.contract={start:state.killCount};api.spawnPatrol();toast('Заказ принят: победите 3 теней на лесной дороге',true);}
  if(action==='claim-contract'){if(!w.contract||state.killCount-w.contract.start<3)return;p.gold+=45;give('ore',3);w.contract=null;toast('Заказ выполнен · +45 монет',true);}
  if(action==='buy-plot'||action==='buy-shack'){if(state.quest<5||w.house.owned)return;if(!pay(action==='buy-plot'?80:220))return;w.house.owned=true;w.house.stage=action==='buy-shack'?4:0;toast(action==='buy-plot'?'Участок принадлежит вам обоим':'У вас с Амо появился дом',true);}
  if(action==='build'){const h=w.house,cost=buildCosts[h.stage];if(!h.owned||!cost||!Object.entries(cost).every(([k,n])=>k==='gold'?p.gold>=n:count(k)>=n))return;for(const[k,n]of Object.entries(cost))if(k==='gold')p.gold-=n;else take(k,n);h.stage++;toast('Амо помогает: '+houseStages[h.stage]+' готов'+(h.stage===2?'ы':''),true);romance.assist('build');}
  if(action==='hearth'){if(w.house.hearth||count('brick')<4){toast('Нужно 4 тёсаных камня');return;}if(!pay(35))return;take('brick',4);w.house.hearth=true;toast('В вашем доме появился очаг',true);}
  if(action==='garden'){if(w.house.garden||count('plank')<3){toast('Нужно 3 доски');return;}if(!pay(30))return;take('plank',3);w.house.garden=true;toast('Амо посадила первые цветы у огорода',true);}
  if(action==='plant'){if(!w.house.garden||w.house.plantedAt!==null)return;if(!take('seed')){toast('Купите семена на рынке');return;}w.house.plantedAt=w.elapsed;toast('Пшеница посажена',true);}
  if(action==='harvest'){if(w.house.plantedAt===null||w.elapsed-w.house.plantedAt<45)return;if(give('wheat',3)){w.house.plantedAt=null;xp(5);toast('Урожай собран: 3 пшеницы',true);}}
  if(action==='enter-home'){travel('home',320,510);return;}
  if(action==='chapel'){travel('chapel',320,525);return;}
  if(action==='amo'){openModal('companion');return;}
  sync();saveGame();renderCurrent();api.updateQuest();
 }
 $('modal-content').addEventListener('click',e=>{if(performance.now()-draggedAt<250)return;const slot=e.target.closest('[data-slot]');if(slot){const next=slot.dataset.slot;if(selected&&selected!==next&&!readSlot(next)&&readSlot(selected)){moveSlot(selected,next);return;}selected=next;renderCurrent();return;}onAction(e);});
 $('modal-content').addEventListener('pointerdown',e=>{const el=e.target.closest('[data-slot]');if(!el||!readSlot(el.dataset.slot)||e.button>0)return;drag={from:el.dataset.slot,x:e.clientX,y:e.clientY,id:e.pointerId,html:el.innerHTML,moved:false};el.setPointerCapture(e.pointerId);});
 $('modal-content').addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;if(!drag.moved&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>7){drag.moved=true;const ghost=document.createElement('div');ghost.id='drag-item';ghost.innerHTML=drag.html;document.body.appendChild(ghost);}if(drag.moved){e.preventDefault();const ghost=$('drag-item');ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';}});
 function dragEnd(e){if(!drag)return;const current=drag;drag=null;$('drag-item')?.remove();if(current.moved){draggedAt=performance.now();const dest=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-slot]');if(dest)moveSlot(current.from,dest.dataset.slot);}}
 $('modal-content').addEventListener('pointerup',dragEnd);$('modal-content').addEventListener('pointercancel',()=>{drag=null;$('drag-item')?.remove();});
 function install(){const group=document.querySelector('.utility-buttons');for(const[id,title,glyph,kind]of[['inventory-button','Инвентарь · I','▦','inventory'],['character-button','Герой · C','♜','character'],['talents-button','Древо умений · T','✥','talents']]){const b=document.createElement('button');b.id=id;b.className='icon-button folio-button';b.title=title;b.setAttribute('aria-label',title);b.textContent=glyph;b.addEventListener('click',()=>openModal(kind));group.prepend(b);}document.querySelector('.player-card').style.pointerEvents='auto';document.querySelector('.player-card').addEventListener('click',()=>openModal('character'));}
 function onClose(){if(busy){toast('Ещё немного — работа почти закончена');return false;}$('modal').querySelector('.modal-card').classList.remove('rpg-folio');return true;}
 romance=createCompanion({...api,stats,give,take,count,travel,itemName:id=>ITEMS[id]?.name||id});reset();install();return{reset,restore,serialize,count,give,take,stats,sync,nearby,interact,onKill,update,renderModal,onClose,travel,hud:()=>romance.hud(),target:()=>romance.target(),bounds:()=>bounds(state.scene),sceneNPCs:()=>sceneNPCs(state)};
}
